# Physical parameter square, exact upper LFT and open-loop responses
def gu(s):
    h = 1/(s*s + .2*s + 1)
    return h*np.array([[-.3*s*s,-.3*s*s,s*s],[-.3,-.3,1],[-.3,-.3,1]],complex)
def close_lft(s,dm,dk):
    M=gu(s);D=np.diag([dm,dk])
    return M[2,2]+M[2,:2]@D@np.linalg.solve(np.eye(2)-M[:2,:2]@D,M[:2,2])
grid=np.linspace(-1,1,11);dm_grid,dk_grid=np.meshgrid(grid,grid)
max_residual=0.
for dm in grid:
    for dk in grid:
        for w in [0,.2,1,3,10]:
            z=1j*w;direct=1/((1+.3*dm)*z*z+.2*z+1+.3*dk)
            max_residual=max(max_residual,abs(close_lft(z,dm,dk)-direct))
print('grid=121; mass/stiffness ranges=[0.7,1.3]; includes all four corners')
print('nominal wn=1 rad/s; zeta=0.1; LFT max absolute residual=',max_residual)
assert max_residual<1e-10
fig,ax=plt.subplots(1,2,figsize=(10,3.7))
ax[0].scatter(dm_grid.ravel(),dk_grid.ravel(),s=12);ax[0].set(xlabel='delta_m',ylabel='delta_k',xlim=(-1.1,1.1),ylim=(-1.1,1.1))
t=np.linspace(0,20,1000)
for name,m,k in [('nominal',1,1),('mass +30%',1.3,1),('stiffness -30%',1,.7),('allowed corner',1.3,.7)]:
    _,y=ctrl.step_response(ctrl.tf([1],[m,.2,k]),t);ax[1].plot(t,y,label=name)
ax[1].set(xlabel='time (s)',ylabel='open-loop position');ax[1].legend(fontsize=8);ax[1].grid();plt.tight_layout();plt.show()
print('physical_model_complete')

# Exact restricted alternating optimization, independent NumPy SVD and exercise values
def matrix(k):return np.array([[0,2-1.5*k],[.125+.675*k,0.]])
def values(k,d):
    A=matrix(k);D=np.diag([d,1.]);return float(np.linalg.svd(D@A@np.linalg.inv(D),compute_uv=False)[0]),float(max(abs(np.linalg.eigvals(A))))
traces=[]
for initial_d in [1.,.25,2.]:
    k=.5;d=initial_d;rows=[('initial',k,d,*values(k,d))]
    for i in range(4):
        k=float(np.clip((2*d*d-.125)/(1.5*d*d+.675),0,1));rows.append(('K',k,d,*values(k,d)))
        A=matrix(k);d=float(np.sqrt(A[1,0]/A[0,1]));rows.append(('D',k,d,*values(k,d)))
    traces.append(rows);print('initial d=',initial_d,'final=',rows[-1])
print('default k=.5 d=1:',values(.5,1),'dopt=',np.sqrt(.4625/1.25))
for k in [0,.5,1]:print('k=',k,'mu=',values(k,1)[1])
fig,ax=plt.subplots(figsize=(8,3.7))
for rows in traces:ax.plot(range(len(rows)),[r[3] for r in rows],marker='o',label='initial d='+str(rows[0][2]))
ax.set(xlabel='substep',ylabel='scaled H-infinity norm');ax.legend();ax.grid();plt.tight_layout();plt.show()
print('dk_complete')
